/**
 * Where in the water each water species lives (the owner's sea-depth fix,
 * 2026-11-11): its depth band, and where in the band it is at any moment.
 *
 * The band is `depth-bands.json`, generated by `scripts/ark-layers.mts`
 * ("Depth bands") from stored data, the deciding phrase kept: surface (ducks,
 * seabirds, sea otters float), upper (whales, dolphins, mantas, tuna), mid
 * (schools, jellyfish), seabed (crabs, stars, urchins, flatfish, resting
 * rays), reef (reef fish; octopus and eels in their holes), deep (on the deep
 * floor or far down in the dark); and fresh water the same: the pond's
 * surface, its mid-water and its bed.
 *
 * Why the sea's animals sat on the water before: the open sea's swimmers
 * were put a fraction of their own height below the surface (0.38–0.5 of it),
 * so their backs rode above it; anything at sea whose model was not loaded
 * yet, or whose body plan was not on the swimming list (eels, flatfish), took
 * the land's rule and floated at -0.28 of its height; the lake's fish stood
 * on its shore; and from afar every animal is drawn up to 2.3 times larger,
 * growing up from its base, so even a reef fish's back broke the surface.
 * Here the body's middle is placed in the band and the whole drawn body is
 * fitted below the surface and above the floor at the size it is drawn.
 *
 * Deterministic and shared: the band from the species, the place in it from
 * the clock and the animal's id (a slow swim up and down its band). An
 * air-breather comes up to breathe on a cycle from the same clock and id
 * (`breathAt`), which the behaviour state reads (`behaviour-state.ts`): the
 * state says "breathing", the pose rises to the surface.
 *
 * Visual only: nothing here changes what happens on the Ark.
 */

import table from "@/ark-scene/depth-bands.json";
import {ARK_ZONES, type ArkZone} from "@/ark-scene/types";
import {arkWorld, coastRadius, hashString, LAKE, sampleGround, ZONE_SITES, onArkWorld} from "@/ark-scene/world";
import {wildWaterSurface} from "@/ark-scene/islands/wild/map-v2";
import {islandWaterNow} from "@/ark-scene/water-level";

export type DepthBand = "surface" | "upper" | "mid" | "seabed" | "reef" | "deep" | "pond_surface" | "pond_mid" | "pond_bed";
export type WaterKind = "salt" | "fresh";
/** Where its water is: its own zone's (the reef, the open ocean), the lake, or the sea off its zone's coast. */
export type WaterHome = "zone" | "lake" | "coast";

export type SpeciesDepth = {
    band: DepthBand;
    water: WaterKind;
    home: WaterHome;
    /** Breathes air: comes up to breathe now and then. */
    breathes: boolean;
    /** Lives in a hole in the reef (octopus, morays): tucked into it at the floor. */
    crevice: boolean;
    /** A deep one that lives on the deep floor. */
    deepFloor: boolean;
    glow: boolean;
    /** The stored phrase, the taxonomy or the body plan that decided it. */
    reason: string;
    /** text, taxonomy, plan, zone, or default (no usable depth data: the band is the default for its body). */
    source: string;
};

type Row = [string, string, string, string, string, string];
const ROWS = (table as unknown as {species: Record<string, Row>}).species;
/** The classifier's reviewed hold list: species at sea that are not water species (a frigatebird, a catalogue error). */
const HELD = (table as unknown as {held?: Record<string, [string, string]>}).held ?? {};
const known = new Map<string, SpeciesDepth | null>();

/**
 * A species the classifier holds off the water (its reviewed hold list,
 * with the reason): it flies over its zone, awake or asleep, and never
 * comes down onto the sea. Null for every other species.
 */
export function heldOffWater(slug: string): {show: "air"; reason: string} | null {
    const row = HELD[slug];
    return row ? {show: "air", reason: row[1]} : null;
}

/** The hold list (for the tests and the report). */
export function heldTable(): Record<string, string> {
    return Object.fromEntries(Object.entries(HELD).map(([slug, row]) => [slug, row[1]]));
}

/** A sea zone's species the table lacks (newer than it): mid-water, flagged as the default. */
function fallback(zone: string): SpeciesDepth | null {
    if (zone !== "coral_reef" && zone !== "open_ocean") return null;
    return {band: zone === "coral_reef" ? "reef" : "mid", water: "salt", home: "zone", breathes: false, crevice: false, deepFloor: false, glow: false, reason: "default: not in depth-bands.json", source: "default"};
}

/**
 * The divers the table leaves out because they live on land between swims
 * (the map lane's fix, 2026-11-11: "penguins floating in the ocean"): the
 * penguins and the seals, sea lions and walrus. On land they stand on their
 * shore (`map/place.ts` haulsOut); in the water, when their schedule takes
 * them swimming, they swim under the surface in the upper water and come up
 * to breathe (porpoising), never float upright on it like a duck.
 */
const DIVERS = /(^|-)penguin($|-)|(^|-)seal($|-)|sea-lion|fur-seal|walrus/;
function diverDepth(slug: string): SpeciesDepth | null {
    if (!DIVERS.test(slug)) return null;
    return {band: "upper", water: "salt", home: "coast", breathes: true, crevice: false, deepFloor: false, glow: false, reason: "a diver that hauls out (penguin, seal, sea lion, walrus): it swims in the upper water and breathes at the surface", source: "default"};
}

/**
 * A swimming body's lean (radians, the scene's pitch: positive tips the head
 * forward): a penguin's model stands upright, so it lies down to swim, belly
 * under, head first (π/2); every other body swims as its model lies (0).
 */
export function swimBodyPitch(slug: string): number {
    return /(^|-)penguin($|-)/.test(slug) ? Math.PI / 2 : 0;
}

/** A species' depth band, or null when it is not a water species (it stands on land, or perches, or is small and at its microhabitat). */
export function speciesDepth(slug: string, zone: string): SpeciesDepth | null {
    const key = `${slug}#${zone}`;
    if (known.has(key)) return known.get(key)!;
    if (HELD[slug]) {
        known.set(key, null);
        return null;
    }
    const row = ROWS[slug];
    const found: SpeciesDepth | null = row
        ? {band: row[0] as DepthBand, water: row[1] as WaterKind, home: row[2] as WaterHome, breathes: row[3].includes("b"), crevice: row[3].includes("c"), deepFloor: row[3].includes("f"), glow: row[3].includes("g"), reason: row[4], source: row[5]}
        : (diverDepth(slug) ?? fallback(zone));
    known.set(key, found);
    return found;
}

/** Every water species in the table (for the tests and the report). */
export function depthTable(): Record<string, SpeciesDepth> {
    return Object.fromEntries(Object.keys(ROWS).map((slug) => [slug, speciesDepth(slug, "")!]));
}

/** How it moves in its band: swims loops in the water, walks slowly on the floor, keeps to its hole, or floats on the surface. */
export type WaterMotion = "swim" | "walk" | "hole" | "float";

export function waterMotion(depth: SpeciesDepth): WaterMotion {
    if (depth.band === "surface" || depth.band === "pond_surface") return "float";
    if (depth.crevice) return "hole";
    if (depth.band === "seabed" || depth.band === "pond_bed" || (depth.band === "deep" && depth.deepFloor)) return "walk";
    return "swim";
}

/** How far below the surface the top of a swimming body is always kept (m). */
export const SURFACE_CLEAR = 0.08;
/** How high above the floor the bottom of a swimming body is kept (m). */
export const FLOOR_CLEAR = 0.05;
/** A floater's base below the surface, as a share of its height: it floats with most of its body under. */
export const FLOAT_SINK = 0.35;
/** A hole-dweller's base below the floor, as a share of its height: tucked into its hole, its front out. */
const HOLE_SINK = 0.15;
/** At the top of a breath, the middle of the body this share of its height below the surface: its back breaks it. */
const BREATH_MIDDLE = 0.2;

/** A seed in 0…1 from an animal's id. */
export function depthSeed(id: string): number {
    return (hashString(`${id}#depth`) % 10000) / 10000;
}

/**
 * The band's range for the body's middle, as depths below the surface (m),
 * in water `waterDepth` deep, for a swimmer: the upper water the top
 * third of the column, mid-water its middle, the deep its lowest part; the
 * reef's swimmers keep within a metre of the floor (as height above it).
 */
export function swimRange(band: DepthBand, waterDepth: number): {from: number; to: number; aboveFloor?: boolean} {
    switch (band) {
        case "upper":
            return {from: 0.12 * waterDepth, to: 0.32 * waterDepth};
        case "mid":
        case "pond_mid":
            return {from: 0.35 * waterDepth, to: 0.62 * waterDepth};
        case "deep":
            return {from: 0.66 * waterDepth, to: 0.86 * waterDepth};
        case "reef":
            return {from: 0.15, to: 0.9, aboveFloor: true};
        default:
            return {from: 0.3 * waterDepth, to: 0.6 * waterDepth};
    }
}

/** Its slow swim up and down its band: 0…1 through the band, from the clock and its seed (a period of 50–110 s). */
export function bandCycle(seed: number, clock: number): number {
    const period = 50 + 60 * ((seed * 7.31) % 1);
    return 0.5 + 0.5 * Math.sin((clock / period + seed) * Math.PI * 2);
}

/** An air-breather's breath cycle: every 70–140 s (twice as long asleep) it rises, takes 3 s of air at the surface, and dives. */
const BREATH_RISE = 2.5;
const BREATH_HOLD = 3;

export function breathPeriod(seed: number, asleep: boolean): number {
    return (70 + 70 * ((seed * 3.17) % 1)) * (asleep ? 2 : 1);
}

/**
 * How far up into its breath it is now: 0 down in its band, 1 at the
 * surface. A pure function of the clock (seconds) and the animal's seed, so
 * every viewer sees the same whale blow at the same moment. The behaviour
 * state's "breathing" is this above 0.
 */
export function breathAt(seed: number, clock: number, asleep = false): number {
    const period = breathPeriod(seed, asleep);
    const at = (((clock + seed * period) % period) + period) % period;
    const window = BREATH_RISE * 2 + BREATH_HOLD;
    if (at >= window) return 0;
    const rise = Math.min(at / BREATH_RISE, 1, (window - at) / BREATH_RISE);
    return rise * rise * (3 - 2 * rise);
}

/** Where a water animal is in the column (independent of how large it is drawn): fitted to its drawn height by `fitInWater`. */
export type WaterSpec = {
    motion: WaterMotion;
    /** The floor's height under it (negative under water). */
    floorY: number;
    /** A swimmer: its middle's depth below the surface (m), or its height above the floor (m) when `aboveFloor`. */
    depth: number;
    aboveFloor: boolean;
    /** 0…1 up into a breath. */
    breath: number;
    /**
     * The water's surface over it (m), where it is not the sea's 0 (Part C: the bigger wild island's lake and river,
     * at their own level; absent everywhere else). Its depths are under it, and the tide never moves it (`tideFit`).
     */
    surface?: number;
};

/** The water's surface over a point (Part C): v2's lake's and river's own level where they stand, else the sea's 0. */
export function waterSurfaceAt(x: number, z: number): number {
    // (Part C, lane TB: another island's own water at its own level, `water-level.ts` setIslandWater.)
    const own = islandWaterNow()?.surface(x, z) ?? null;
    if (own !== null) return own;
    return arkWorld() === "v2" ? wildWaterSurface(x, z) : 0;
}

/** Its place in the column now, from its band, the floor under it, the clock and its seed, and how far into a breath it is. */
export function waterSpec(depth: SpeciesDepth, floorY: number, seed: number, clock: number, breath: number, surface = 0): WaterSpec {
    const motion = waterMotion(depth);
    const waterDepth = Math.max(surface - floorY, 0);
    const range = swimRange(depth.band, waterDepth);
    const u = bandCycle(seed, clock);
    const spec: WaterSpec = {motion, floorY, depth: range.from + (range.to - range.from) * u, aboveFloor: Boolean(range.aboveFloor), breath: depth.breathes ? breath : 0};
    // (Only a surface of its own: the sea's columns stay exactly as they were.)
    if (surface) spec.surface = surface;
    return spec;
}

/**
 * The body's base (its lowest point's height) for a body drawn `height`
 * tall: a floater floats, a floor-dweller stands on the floor (in its hole,
 * a little into it), a swimmer has its whole body under the surface and
 * above the floor (under the surface first, where the water is too
 * shallow for both), except in a breath, when it rises until its back
 * breaks the surface.
 */
export function fitInWater(spec: WaterSpec, height: number): {base: number; middle: number} {
    // (Its surface: the sea's 0, or the bigger island's lake's and river's own level.)
    const top = spec.surface ?? 0;
    if (spec.motion === "float") {
        const base = top - FLOAT_SINK * height;
        return {base, middle: base + height / 2};
    }
    if (spec.motion === "walk" || spec.motion === "hole") {
        const base = spec.floorY - (spec.motion === "hole" ? HOLE_SINK * height : 0);
        // A breather on the floor still comes up for air.
        const middle = base + height / 2;
        const up = spec.breath > 0 ? middle + (top - BREATH_MIDDLE * height - middle) * spec.breath : middle;
        return {base: up - height / 2, middle: up};
    }
    let middle = spec.aboveFloor ? spec.floorY + FLOOR_CLEAR + height / 2 + spec.depth : top - spec.depth;
    // Above the floor, then under the surface (which wins where the water is too shallow for both).
    middle = Math.max(middle, spec.floorY + FLOOR_CLEAR + height / 2);
    middle = Math.min(middle, top - SURFACE_CLEAR - height / 2);
    if (spec.breath > 0) middle += (top - BREATH_MIDDLE * height - middle) * spec.breath;
    return {base: middle - height / 2, middle};
}

/**
 * A school's, a pod's or a pair's member beside its first one, in the first
 * one's frame (`side` metres to its right, `back` behind): side by side,
 * one each side in turn, rank 1 and 2 a row out, 3 and 4 the next; each row
 * 1.3–1.6 body lengths (seeded) from the last, and seeded a little back. So
 * members swim level with each other, never stacked and never touching: the
 * nearest two are always at least 1.3 body lengths apart across the line of
 * travel, and a body is narrower than it is long.
 */
export function schoolOffset(rank: number, seed: number, length: number): {side: number; back: number; gap: number} {
    if (rank <= 0) return {side: 0, back: 0, gap: 0};
    const row = Math.ceil(rank / 2);
    const gap = length * (1.3 + 0.3 * seed);
    return {side: (rank % 2 ? 1 : -1) * row * gap, back: length * 0.4 * ((seed * 5.3 + rank * 0.37) % 1), gap};
}

/** Where the water is too shallow beside the first one: the member falls in behind instead, a gap per rank (on the first one's loop). */
export function schoolFile(rank: number, seed: number, length: number): {side: number; back: number} {
    const {gap} = schoolOffset(rank, seed, length);
    return {side: 0, back: rank * gap};
}

/**
 * A gentle pitch while it changes depth (radians, nose up rising): from its
 * swim up and down the band against how fast it swims along its loop, at
 * most 0.2. Level when its depth holds still.
 */
export function swimPitch(depth: SpeciesDepth, waterDepth: number, seed: number, clock: number, along: number): number {
    if (waterMotion(depth) !== "swim" || along <= 1e-6) return 0;
    const range = swimRange(depth.band, waterDepth);
    const period = 50 + 60 * ((seed * 7.31) % 1);
    // d(depth)/dt of the band cycle (m/s); rising when the depth shrinks.
    const sink = (range.to - range.from) * 0.5 * Math.cos((clock / period + seed) * Math.PI * 2) * Math.PI * 2 / period;
    const pitch = Math.atan2(sink * (range.aboveFloor ? -1 : 1), along);
    // Three.js: a positive pitch about x turns the nose (+z) down; sinking is nose down.
    return Math.min(Math.max(pitch, -0.2), 0.2);
}

/** Its loop's pace in the water, as a share of a swimmer's: a crab walks, a duck drifts, an octopus keeps to its hole. */
export function waterPace(motion: WaterMotion): number {
    return motion === "swim" ? 1 : motion === "walk" ? 0.3 : motion === "float" ? 0.35 : 0;
}

/** How wide its loop is (m), from its seed and length: a swimmer's wide, a walker's and a floater's small. */
export function waterLoopRadius(motion: WaterMotion, seed: number, length: number): number {
    if (motion === "hole") return 0;
    if (motion === "walk") return 0.4 + seed * 0.8 + length * 0.4;
    if (motion === "float") return 0.6 + seed * 1.2 + length * 0.5;
    return 2.2 + seed * 3 + length * 0.6;
}

const safeLoops = new Map<string, number>();
/** The water under a loop is at least this deep everywhere round it (m). */
const LOOP_FLOOR = -0.6;

/**
 * The widest loop up to `radius` about a spot that stays over water at
 * least 0.6 m deep all the way round (sixteen points looked at), so a reef
 * fish never swims up the beach. Pure, and remembered per spot.
 */
export function safeLoopRadius(x: number, z: number, radius: number): number {
    const key = `${x.toFixed(2)},${z.toFixed(2)},${radius.toFixed(2)}`;
    const known = safeLoops.get(key);
    if (known !== undefined) return known;
    let r = radius;
    const v2 = arkWorld() === "v2";
    for (; r > 0.3; r *= 0.8) {
        let wet = true;
        for (let k = 0; k < 16 && wet; k++) {
            const a = k / 16 * Math.PI * 2;
            wet = v2 ? waterOver(x + Math.cos(a) * r, z + Math.sin(a) * r) > -LOOP_FLOOR : sampleGround(x + Math.cos(a) * r, z + Math.sin(a) * r).height < LOOP_FLOOR;
        }
        if (wet) break;
    }
    const safe = Math.max(r, 0.3);
    if (safeLoops.size > 4000) safeLoops.clear();
    safeLoops.set(key, safe);
    return safe;
}

// MARK: Its water: the lake, or the sea off its zone's coast

const GOLDEN_ANGLE = Math.PI * (3 - Math.sqrt(5));
/** The lake's swimmers keep this far inside its middle (m): its edge wanders by a metre, and the shallows are the lily pads'. */
export let LAKE_SWIM_RADIUS = LAKE.r - 3;
// (Follows the world's switch: the v2 world's lake is bigger. docs/ark/wild-island.md §Integration.)
onArkWorld(() => {
    LAKE_SWIM_RADIUS = LAKE.r - 3;
    // (And the spots and loops worked out on the other world's water.)
    lakeSpots = null;
    coastGrids.clear();
    safeLoops.clear();
});
const LAKE_SPACING = 2.1;
const COAST_SPACING = 3;
const COAST_OUT = 12;

/**
 * Metres of water over a point on the v2 world (the bigger wild island, Part C): the sea's below its level 0, and the
 * lake's, the river's and the pools' over their own beds, at their own level (`water-level.ts` freshLevelAt), which
 * stands above the sea. Negative on dry ground (how far above the water it is).
 */
function waterOver(x: number, z: number): number {
    return freshOver(x, z) ?? -sampleGround(x, z).height;
}

/** On v2: the fresh water's depth over a point (the lake's, the river's, a pool's), or null where it is not fresh water. */
function freshOver(x: number, z: number): number | null {
    const s = sampleGround(x, z) as ReturnType<typeof sampleGround> & {fresh?: number; freshLevel?: number | null};
    return s.freshLevel !== null && s.freshLevel !== undefined && (s.fresh ?? 0) >= 0.5 && s.height < s.freshLevel ? s.freshLevel - s.height : null;
}

/** Is a point the right water for this home: deep enough sea off the coast, or the lake's open water. */
export function inHomeWater(home: "lake" | "coast", x: number, z: number): boolean {
    // (v2: the lake stands above the sea at its own level, so its open water is 0.9 m deep over its bed, not below 0.)
    if (home === "lake" && arkWorld() === "v2") return Math.hypot(x - LAKE.x, z - LAKE.z) <= LAKE_SWIM_RADIUS && (freshOver(x, z) ?? 0) > 0.9;
    if (home === "lake") return Math.hypot(x - LAKE.x, z - LAKE.z) <= LAKE_SWIM_RADIUS && sampleGround(x, z).height < -0.9;
    const ground = sampleGround(x, z);
    return ground.inland < -2 && ground.height <= -1.4 && Math.hypot(x - LAKE.x, z - LAKE.z) > LAKE.r + 6;
}

let lakeSpots: Array<{x: number; z: number}> | null = null;
function lakeSpot(index: number): {x: number; z: number} {
    if (!lakeSpots) {
        // The lake's open water on a spiral, LAKE_SPACING apart (about forty spots).
        lakeSpots = [];
        for (let k = 0; ; k++) {
            const radius = LAKE_SPACING / Math.sqrt(Math.PI) * Math.sqrt(k + 0.5);
            if (radius > LAKE_SWIM_RADIUS) break;
            const x = LAKE.x + Math.cos(k * GOLDEN_ANGLE) * radius;
            const z = LAKE.z + Math.sin(k * GOLDEN_ANGLE) * radius;
            if (inHomeWater("lake", x, z)) lakeSpots.push({x, z});
        }
    }
    const n = Math.max(lakeSpots.length, 1);
    const base = lakeSpots[index % n] ?? {x: LAKE.x, z: LAKE.z};
    // Past the spots, round again a little turned (swimmers loop, so a shared spot is never a stack).
    const lap = Math.floor(index / n);
    if (!lap) return base;
    const angle = lap * 2.4;
    const turned = {x: LAKE.x + (base.x - LAKE.x) * Math.cos(angle) - (base.z - LAKE.z) * Math.sin(angle), z: LAKE.z + (base.x - LAKE.x) * Math.sin(angle) + (base.z - LAKE.z) * Math.cos(angle)};
    // (v2: the lake's shore wanders, so a spot turned about its middle may fall in its shallows or on its bank: the
    // nearest of its open water's spots then, a lap round, so laps never stack.)
    if (arkWorld() !== "v2" || inHomeWater("lake", turned.x, turned.z)) return turned;
    let best = base;
    let distance = Infinity;
    for (const spot of lakeSpots) {
        const d = Math.hypot(spot.x - turned.x, spot.z - turned.z);
        if (d < distance) {
            distance = d;
            best = spot;
        }
    }
    const r = Math.min(0.5 + 0.35 * lap, LAKE_SPACING * 0.45);
    for (let k = 0; k < 12; k++) {
        const x = best.x + Math.cos(lap * 2.4 + k * 0.52) * r;
        const z = best.z + Math.sin(lap * 2.4 + k * 0.52) * r;
        if (inHomeWater("lake", x, z)) return {x, z};
    }
    return best;
}

const coastGrids = new Map<string, {spots: Array<{x: number; z: number}>; next: number}>();
/** The sea off a zone's own coast: out from the coast at the zone's bearing (the beach's for the shore). */
function coastSpot(zone: ArkZone, index: number): {x: number; z: number} {
    let grid = coastGrids.get(zone);
    if (!grid) {
        grid = {spots: [], next: 0};
        coastGrids.set(zone, grid);
    }
    const site = ZONE_SITES[zone];
    const theta = site.theta ?? Math.atan2(site.z, site.x);
    const r = coastRadius(theta) + COAST_OUT;
    const cx = Math.cos(theta) * r;
    const cz = Math.sin(theta) * r;
    while (grid.spots.length <= index && grid.next < 3000) {
        const k = grid.next++;
        const radius = COAST_SPACING / Math.sqrt(Math.PI) * Math.sqrt(k + 0.5);
        const x = cx + Math.cos(k * GOLDEN_ANGLE) * radius;
        const z = cz + Math.sin(k * GOLDEN_ANGLE) * radius;
        if (inHomeWater("coast", x, z)) grid.spots.push({x, z});
    }
    return grid.spots[Math.min(index, grid.spots.length - 1)] ?? {x: cx, z: cz};
}

/**
 * A water species' spot when its zone's own place is not its water (a
 * fresh-water fish of the farm, the forest or the lake's shore: the lake; a
 * sea fish of the shore or the ice: the sea off that coast), from its zone,
 * slot and rank alone like every other place. Null when its zone's own
 * place is its water (the reef, the open ocean).
 */
export function waterHomeSpot(depth: SpeciesDepth, zone: ArkZone, slot: number, rank: number, length = 0): {x: number; z: number; home: "lake" | "coast"} | null {
    const home: "lake" | "coast" | null = depth.water === "fresh" ? "lake" : depth.home === "coast" || ZONE_SITES[zone]?.kind !== "sea" ? "coast" : null;
    if (!home) return null;
    const zoneIndex = Math.max(ARK_ZONES.indexOf(zone), 0);
    // The lake's spots are shared by every zone's fresh-water animals: slot k of zone Z takes spot k · zones + Z.
    const centre = home === "lake" ? lakeSpot(slot * ARK_ZONES.length + zoneIndex) : coastSpot(zone, slot);
    if (rank === 0) return {...centre, home};
    // Its cluster's others about it, in its water, about 1.3 body lengths apart (a spiral's neighbours are 1.5 c apart).
    const turn = (hashString(`${zone}#${slot}#water`) % 360) / 180 * Math.PI;
    const c = Math.max(0.95, 0.9 * length);
    for (let k = rank; k < rank + 40; k++) {
        const radius = c * Math.sqrt(k);
        const x = centre.x + Math.cos(k * GOLDEN_ANGLE + turn) * radius;
        const z = centre.z + Math.sin(k * GOLDEN_ANGLE + turn) * radius;
        if (inHomeWater(home, x, z)) return {x, z, home};
    }
    return {...centre, home};
}
